import pathlib,json,collections,gzip
out=pathlib.Path(__file__).resolve().parents[1];p=out/'continuation'
def load(name):
 path=p/name
 if not path.exists():return json.loads(gzip.decompress(pathlib.Path(str(path)+'.gz').read_bytes()))
 return json.loads(path.read_text())
def code(value):return '`'+str(value).replace('|','\\|').replace('\n',' ')+'`'
def quote(value):return '\n````json\n'+json.dumps(value,indent=2,ensure_ascii=True)+'\n````\n'
def rows(path):
 if not path.exists():path=pathlib.Path(str(path)+'.gz')
 with (gzip.open(path,'rt') if path.suffix=='.gz' else path.open()) as stream:
  result=[]
  for line in stream:
   try:result.append(json.loads(line))
   except ValueError:pass
  return result
def category(r):
 old={(x['kind'],x['reason']) for x in r['baseline_findings']}
 if not r['complete_stream']:return 'incomplete'
 if r['checker_diagnostics'] or r['go_checker_diagnostics']:return 'checker diagnostic'
 if r['findings']:return 'replacement finding' if any((x['kind'],x['reason']) not in old for x in r['findings']) else 'unchanged finding'
 return 'cleared at original view' if r['verdict']=='no finding at original call; unit attempted' else 'unit excluded or not attempted'
